css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; inset: 0; border: calc(var(--loader-size) * .035) solid var(--accent); border-radius: 10%; animation: tunnel calc(var(--loader-speed) * 2.4) linear infinite; }
.loader span:nth-child(even) { border-color: var(--accent-2); }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * -.6); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * -1.2); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * -1.8); }
@keyframes tunnel { 0% { transform: scale(1) rotate(0deg); opacity: 0; } 15% { opacity: 1; } 100% { transform: scale(.05) rotate(90deg); opacity: 0; } }
